// Command kiln-dep finds undeclared build dependencies.
//
// It runs Ninja under a seccomp/ptrace tracer, records every file each build
// step opens, and compares that with the graph Ninja knows (build.ninja plus
// recorded depfiles). It reports:
//
//   - undeclared-generated-input: a step reads a generated file whose producer
//     is not ordered before it. Clean parallel builds can fail or use stale files.
//   - undeclared-source-input: a step without a depfile reads a source file it
//     does not declare, so editing that file does not rebuild the output.
//   - write-outside-build-dir: a step writes into the source tree.
//
// Usage: kiln-dep -C build -src . [-clean] [-j 8] [-json report.json] [targets...]
// Exit status is 1 when anything is found (use -warn-only to always exit 0).
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"

	"github.com/7shantanu7/kiln/internal/depcheck"
	"github.com/7shantanu7/kiln/internal/ninja"
	"github.com/7shantanu7/kiln/internal/sandbox"
)

func init() { sandbox.Shim() }

func main() {
	dir := flag.String("C", "build", "configured Ninja build directory")
	src := flag.String("src", ".", "source root")
	clean := flag.Bool("clean", false, "run `ninja -t clean` first so every step is traced")
	jobs := flag.Int("j", 0, "parallel jobs for Ninja (0 = Ninja's default)")
	jsonOut := flag.String("json", "", "also write the report as JSON to this file")
	keepGoing := flag.Bool("keep-going", true, "pass -k 0 to Ninja so one failing step does not stop the trace")
	maxPasses := flag.Int("passes", 3, "when the build fails, rerun Ninja (traced) up to this many times in total")
	warnOnly := flag.Bool("warn-only", false, "exit 0 even when undeclared dependencies are found")
	flag.Parse()

	buildDir, err := filepath.Abs(*dir)
	check(err)
	srcRoot, err := filepath.Abs(*src)
	check(err)
	if *clean {
		out, err := exec.Command("ninja", "-C", buildDir, "-t", "clean").CombinedOutput()
		if err != nil {
			fail("ninja -t clean: %v: %s", err, out)
		}
	}
	commands, err := ninja.Commands(buildDir)
	check(err)
	argv := []string{"ninja", "-C", buildDir}
	if *keepGoing {
		argv = append(argv, "-k", "0")
	}
	if *jobs > 0 {
		argv = append(argv, "-j", strconv.Itoa(*jobs))
	}
	argv = append(argv, flag.Args()...) // targets, built in the order given
	// A step that hit a race often fails, and Ninja then skips everything
	// that depends on it. Rerunning lets the failed step succeed now that its
	// input exists (its read then shows the race) and traces the skipped
	// steps. A pass that runs no step successfully means real errors: stop.
	var passes []*sandbox.Result
	for pass := 1; pass <= *maxPasses; pass++ {
		fmt.Fprintf(os.Stderr, "kiln-dep: pass %d: tracing %v\n", pass, argv)
		res, err := sandbox.Run(buildDir, argv, os.Stderr, os.Stderr)
		check(err)
		passes = append(passes, res)
		if res.ExitCode == 0 {
			break
		}
		fmt.Fprintf(os.Stderr, "kiln-dep: pass %d: build exited with %d\n", pass, res.ExitCode)
		if !madeProgress(res) {
			break
		}
	}
	if last := passes[len(passes)-1]; last.ExitCode != 0 {
		fmt.Fprintf(os.Stderr, "kiln-dep: warning: build still fails after %d passes; analysing the steps that ran\n", len(passes))
	}

	g, err := ninja.Load(buildDir)
	check(err)
	rep := depcheck.Check(g, passes, srcRoot, commands)

	fmt.Printf("kiln-dep: traced %d build steps in %d pass(es), checked %d reads\n", rep.Steps, len(passes), rep.Reads)
	if rep.Steps == 0 {
		fmt.Println("kiln-dep: nothing was rebuilt; use -clean to trace a full build")
	}
	counts := map[string]int{}
	for _, f := range rep.Findings {
		counts[f.Kind]++
		switch f.Kind {
		case depcheck.KindRace:
			if f.Missing {
				fmt.Printf("  %s\n      looked for generated file %s before it existed (the race happened in this build)\n", f.Step, f.File)
			} else if f.Producer == f.File {
				fmt.Printf("  %s\n      reads generated file %s, but the step that generates it is not ordered before it\n", f.Step, f.File)
			} else {
				fmt.Printf("  %s\n      reads %s, generated by %s, which is not ordered before it\n", f.Step, f.File, f.Producer)
			}
		case depcheck.KindStale:
			fmt.Printf("  %s\n      reads %s, which it does not declare\n", f.Step, f.File)
		default:
			fmt.Printf("  %s\n      writes %s outside the build directory\n", f.Step, f.File)
		}
	}
	if len(rep.Findings) == 0 {
		fmt.Println("kiln-dep: no undeclared dependencies")
	} else {
		fmt.Printf("kiln-dep: %d undeclared dependencies (%d generated inputs, %d source inputs, %d outside writes)\n",
			len(rep.Findings), counts[depcheck.KindRace], counts[depcheck.KindStale], counts[depcheck.KindOutsideWrite])
	}
	if *jsonOut != "" {
		b, _ := json.MarshalIndent(rep, "", "  ")
		check(os.WriteFile(*jsonOut, append(b, '\n'), 0o644))
	}
	if len(rep.Findings) > 0 && !*warnOnly {
		os.Exit(1)
	}
}

// madeProgress reports whether any step in the pass wrote a file.
func madeProgress(res *sandbox.Result) bool {
	for _, child := range res.Children(res.Root) {
		for _, p := range res.Subtree(child) {
			for _, a := range p.Accesses {
				if a.Write && !a.Missing {
					return true
				}
			}
		}
	}
	return false
}

func check(err error) {
	if err != nil {
		fail("%v", err)
	}
}

func fail(format string, args ...any) {
	fmt.Fprintf(os.Stderr, "kiln-dep: "+format+"\n", args...)
	os.Exit(2)
}
